using System.Collections.Generic;

namespace osu.Game.Rulesets.Danmakusu.Bosses
{
    /// <summary>What a boss does, in a few sentences (shown in the boss menu), in two parts: what she shoots herself, and what else she does. The mechanics that are built have a text, the others are placeholders.</summary>
    public static class BossDescriptions
    {
        private const string stars = "Spirals of stars.";

        private static readonly Dictionary<BossMechanic, (string Basic, string Mechanics)> texts = new Dictionary<BossMechanic, (string Basic, string Mechanics)>
        {
            [BossMechanic.Blindness] = ("A ring of arrowheads every beat, flying straight.", "Every attack halves the speed of all bullets and turns a flashlight on: you can only see a small circle round you. The pauses restore everything."),
            [BossMechanic.Moon] = (stars, "A big moon and a laser of six lines of stars circle the centre of the screen. Bullets vanish in the moon, but touching it hurts like a slider. All bullets are doubled in size and number, and her attack never pauses."),
            [BossMechanic.ButterflyFans] = ("Petals instead of stars.", "Her tree grows from the bottom of the screen; it grows 32 flowers of its own in every attack and every bullet that leaves the bottom in an attack grows one more (also while the tree grows: the flowers come out on the branches as soon as these have grown there), and in the end the petals fly off. Bullets that leave the top turn into petals and fall again."),
            [BossMechanic.Echo] = ("Paper talismans, in rings that turn the other way whenever new walls appear.", "Two glass walls close in during every attack (top and bottom, then left and right...). Every bullet bounces off them twice, then passes through."),
            [BossMechanic.Doors] = ("Talismans: backwards in an attack, forwards in the pauses.", "Portals open in the wall behind her and behind you; what comes out flies its own way, and a beam that has gone through keeps going in and coming out where the portals were when it first did."),
            [BossMechanic.Dowsing] = ("Arrowheads that fly straight.", "No pauses. Every sixteen beats the bullets round her turn into homing arrowheads and falling ellipses, twice as fast as they flew."),
            [BossMechanic.FantasySeal] = ("Paper talismans. Every few beats a ring of three yin-yang orbs that ricochet until the pause ends.", "During an attack every second bullet cannot leave the screen (the others fly out as ever): they stop at the border and pile up, spread evenly all round it and packed tight, body against body. When the pause ends, the pile is gone."),
            [BossMechanic.FateSpear] = ("Knives; late in her attacks with two, three and four blades, every blade hurting all along it.", "Everything glows red, and a huge aimed spear of knives follows a short warning."),
            [BossMechanic.Freeze] = ("Arrowheads that fly straight.", "Her attack freezes every second bullet in the air at once, then lets them shatter outwards."),
            [BossMechanic.Gaps] = (stars, "Gaps open in the screen; bullets that go into one come out of another. A train comes at you when an attack begins and again in every pause. In every pause three bullets of every eight on the screen freeze and turn into talismans facing the middle of the screen; when the pause ends they fly at it, still talismans, through it and on out of the screen."),
            [BossMechanic.Lunatic] = ("Rings of twenty-five very short straight beams from a fixed spot.", "In every second attack every second bullet freezes in a dim purple light, then slides three circles to the left or the right (harmless and unseen while it slides: a red copy shows where it goes); the others fly on. Every slice of a beam that is out of the playfield when its freeze comes is cut away at once."),
            [BossMechanic.MasterSpark] = ("Master Sparks: they start a circle wide and swell, ever more slowly, until they reach 4.9 circle radii from their middle to each side, then run straight, straight lines with thin edges, while she stands still (with another boss on the screen she keeps all of them). She stands where a boss stands, opposite you, but half as far from the middle of the screen. They come out fast, aimed at you, and keep that one way while they grow; once grown they choose which way round to turn (the way you are nearer right then) and turn towards you, five degrees a second, always that way round, and no mechanic of any boss touches them: nothing stops, turns, cuts, hides, thickens or recolours them.", "In her attacks every third bullet on the screen is a star that ricochets."),
            [BossMechanic.Nuclear] = ("Slow giant orbs that grow out of the middle of the screen (wherever she is) with a heavy thud and burst into dense rings; they hurt like a slider body, and nothing can destroy them (the black hole, the other bosses' mechanics: they can only be frozen, pushed or sent through portals). Every ring of them is turned between the balls of the last.", "Her attacks and pauses last twice as long. Before each of her pauses everything on the screen slows to a stop and the black hole's music starts; in the pause a black hole in the middle, bending the light round it (every bullet near it is stretched into an arc, with a ring of light at its edge and bent stars round it), pulls everything but her big balls and Yuyuko's petals in at half speed (what the circles and sliders fire then comes in from outside the screen, straight at it), swallows what touches it (it shrinks away) and, all through the pause, shoots each of them out again split in two, one out of each of its two rays. Its cone of light shows where they go: it appears before the hole, aimed at you, and stands still; when the first bullet comes out the rays choose which way round to turn (towards you, right then) and turn that way slowly, half a turn at most."),
            [BossMechanic.FreeFall] = ("Ellipses instead of stars.", "In an attack the bullets that leave the top stop there and fall freely, and every second one that comes inside her golden circle round you turns towards you, glowing gold. In the pauses new bullets ricochet one time more. She stands where the boss beside her does not: in the middle when that one stands opposite you, opposite you when it is in the middle; with two others always in the middle. Alone on the map, in every attack she does what another boss does instead, one of all the bosses with a mechanic of their own, with half its bullets."),
            [BossMechanic.Purification] = ("Slices of beam. Every slider of her section is a sliderwhistle, but its laser is fired from her, along the slider's path.", "Every slice of a beam is see-through and harmless for its first four beats. Every 8 beats she shoots every fourth bullet that appeared in them out again, as one ring at their average speed. What the other bosses do to beams only touches hers once a slice is fully formed."),
            [BossMechanic.Rebirth] = ("Nothing of her own but what her landings send out: twenty rings in a spiral.", "No pauses. She jumps at you in a straight line to the edge of the screen and stays there with a huge ball growing on her. Each landing shakes the screen. When the map's last boss section is over she comes back 8 beats later until the end, with everything twice as big; with Kaguya on the map both of them come back, each on her own half of everything."),
            [BossMechanic.ScreenMirror] = ("A ring of plain round bullets every beat, no big beams.", "In her attacks the whole playfield, cursor included, turns upside down. What is flying when the turn starts bounces once off the border and turns red. Four beats before every turn a see-through clone of her, with her magic circle and warning stars, shows where she will be seen after it, red arrows of her dress round you flash and point at her and a circle of them round her points in at her, and the whole screen fills with big see-through arrows, the ones on her dress: red ones flowing sideways and blue ones up or down, from the side you are nearer to towards the other, where the turn will throw you. After every turn a big red circle shows where you are (after the turn upside down it stays round you until the screen turns back), and while the screen is upside down a big see-through red glow lies round you."),
            [BossMechanic.Shikigami] = ("Fast bouncing bullets: arrowheads, every second one a basic bullet that flies straight.", "In every attack she is thrown across the screen."),
            [BossMechanic.Taiko] = (stars, "Five taiko drums circle her and are beaten in turn; each beat sends out a ripple that makes bullets swell, and so does every hit with a finish hitsound, from where it is hit; while a bullet is swollen it hurts like a slider body and is not used up."),
            [BossMechanic.Dango] = ("Round bullets.", "Every bullet leaves two copies behind it, and every second three is skewered like dango: a thin beam runs through them, sticking out in front and behind, and hurts like a slider body, for as long as all three are there. Big bullets, fired with a heavy thud, turn the others round."),
            [BossMechanic.ThreeWorlds] = ("Three planets fire different patterns at once; hit orbs ricochet off the border and off each other.", "While thrown, the Earth and the Moon each swallow the bullets they touch (unseen) and shoot them all out of their edges at every impact as five rings, one right after the other, each spread evenly over 180 degrees away from the wall (what they shoot out they leave alone). Whenever they are not swallowing, the Earth and the Moon push bullets away, with a flash. A throw is never cut short: when the attack ends each flies on to its next impact first. Every 32 beats of an attack (not in one shorter than that) comes the World's Ender, with a warning, one at a time, the last going first; it takes the Earth and the Moon as they are, their chains breaking and every link flying off as a bullet, and goes through to its end also when her section is over. Over four beats, while the screen shakes, the Earth goes to the middle of the screen and grows as big as the playfield is high, under the bullets; once it has grown it hurts like a slider body, and so do all the chunks that come off it and the very big chunks of its halves, while they can be seen; the Moon goes very slowly round it, off its chain, its edge just touching the left and right walls, and the Sun shrinks. Four beats later the Sun crosses the Earth once from one side to the other, along the line that pointed at you at the start, leaving a jagged line of molten rock, and fades out, and orange cracks come up all over the Earth as it begins; the screen shakes until the split. Small, strongly glowing golden bullets, at speeds from half to one and a half times a plain bullet's, fly off to both sides all along the line as it passes, and away from the Earth at both ends, in chaotic bursts over 90 degrees, and chunks of the Earth break away there, leaving holes in it with molten edges, and fly off at one speed, molten at their broken edges. Two beats after the cut it splits. Right before that comes an impact frame of 200 ms: a white screen, everything black with a sharp white arc on the side towards the middle, long sharp stars with straight tails, each with its echoes, that jump about, never crossing, and turn what is under them inside out, sharp lines out from the split, and sharp streaks towards it that go on through the explosion, after which the bullets blur towards the split and the screen shakes hard, both dying away over eight beats. At the split the bullets come again, the other chunks break away at both ends with many more all along the cut, and the halves, cracking into very big chunks with molten edges, drift slowly off to the sides of the line, fanning out over 120 degrees."),
            [BossMechanic.TimeStop] = ("Knives.", "In an attack everything on the screen stands still while spirals of knives appear round her, and a faint green knife for everything, her knives too, and for what is fired meanwhile and flies on, shows where the mirroring will put it, if that is within four circle radii of you (but not within two: those are cleared). When it ends, every bullet within two circle radii of you is gone, everything else is mirrored and turns into knives, and the held knives fly out at you."),
            [BossMechanic.Unconscious] = ("Hearts, twice as big, twice as many in every ring as a boss's stars (in a spinner too).", "Bullets fire from random positions around you."),
            [BossMechanic.Unknown] = (stars, "Bullets whose shape and colour you can only make out when they are close. Her UFOs - black, red and blue, hurting like a slider body - suck in every fourth bullet and shoot each one out four times. Two beats before they are sent, see-through UFOs stand where they will land."),
            [BossMechanic.Winter] = ("Arrowheads that fly straight.", "No pauses. Every slider is a sliderwhistle and shoots its beams; the beam is eaten away from its oldest end at half the speed it grew, each slice dissipating into small slow bullets as it goes that fly against the way the slider goes."),
            [BossMechanic.Darkness] = ("Rings of plain bullets that turn slowly.", "No pauses. Every eight beats she throws a ring of ten invisible circles; whatever is inside one - bullets and beams - cannot be seen, and is half see-through over the edge (the other bosses' own things, like Yukari's trains, stay as they are). The circles do nothing to you, and what they hide still hurts."),
            [BossMechanic.Bats] = ("Bats: everything she shoots is one.", "Every twentieth bullet on the screen turns into a bat. Bats fly as fast as Byakuren's beams and home in on you as they do, twice as fast as arrowheads turn: for eight beats they always turn back, even from past the edge of the screen, then they fly straight on; one that has stayed within two circle radii of you for four beats in all fades out. Bats dim the bullets around them."),
            [BossMechanic.SevenElements] = ("Squares of plain bullets.", "No pauses. Every eight beats the element changes. Fire: ripples turn bullets orange; their red rings flash before they swell, turn yellow and burn out. Water: of the bullets the thick blue ripples catch, every second one gets a see-through, harmless clone that rides the ripple outwards, on three rings side by side across it (each spread evenly over its visible part); four beats later the bullet is gone and its clone is solid, and four beats after that it leaves the ripple and flies on as the bullet did; the others slow to an eighth and slowly recover. Wood: every tenth bullet that leaves the playfield grows a glowing tree, whose ten leaves are thrown slowly at the centre. Metal: every bullet touched gets a frozen knife on top of it that aims at you, then flies. Earth: every twentieth bullet on the screen is a glowing brown stone as big as a circle that bursts into five bullets of its old size when it hits the wall."),
            [BossMechanic.Web] = ("Spider webs of beams, one every sixteen beats, from where she is: twenty-five threads out from the middle and arcs between them, rung after rung, after a see-through preview of eight beats.", "No pauses. A web grows from its middle over eight beats as Mai's snowflake does, swaying slowly, and is taken away from the middle out over the next eight; it hurts like a slider body. Every second bullet that flies into it is caught there and sways with it, and flies on the way it went when the web is taken away where it hangs."),
            [BossMechanic.Onbashira] = ("Five circles of talismans twice as big as a bullet, each with two gaps across from each other, when an attack begins and every eight beats in it: each comes out of the edge of her magic circle, growing to its size over eight beats, and they fly straight away from her at once, their talismans going very slowly round each circle until it stops turning eight beats later; then every talisman flies off straight out from the middle of its circle at half a bullet's speed, red arrows beside them showing the way for two beats before.", "She always stands in the middle. In her section everything a boss shoots - bullets, beams, her own talismans - turns round the first time it has wholly left the screen, flies back the way it came; what bosses shoot is red until then and blue after."),
            [BossMechanic.Masks] = ("Very dense rings of bullets every two beats, of her mood.", "No pauses. Every eight beats her mood changes, with a giant see-through mask on the background and the sound of falling petals, and everything on the screen takes it on, glowing: purple - arrowheads aimed at you (when the mood comes, or when they are fired); blue - ellipses pulled towards you; aquamarine - stars that ricochet off the edge three times; orange - everything falls to the bottom, keeping its way, and for two beats before that an orange arrow beside every second bullet shows the way it will fall."),
            [BossMechanic.Dolls] = ("Every two beats each of her twelve fumos shoots a stream - half of them at you, the others thirty degrees to either side of you: an arrowhead, a plain bullet, an ellipse that falls on towards you and a ricochet star, one after another, with a beam as long as the stream on either side of it, flying ten degrees out to its own side.", "No pauses. Her twelve fumos come out of her and wander slowly all over the screen, standing still while they shoot, each on a yellow magic circle; they do not hurt, their streams and beams do (the beams like a slider)."),
            [BossMechanic.Trumpet] = (stars, "Her attacks last twice as long as other bosses'; in the last two beats of each her rings and the screen flash red. In her attacks the circles and sliders are green and glow, a ring of green arrows closing in on each instead of its number, and they hurt nothing: they shoot neither bullets nor beams, but each, when it is hit (a slider at its head), sends out a thick white ring that hurts like a slider body. Within one circle radius round each of them (from when it comes until four beats after it is hit; along a slider until four beats after it ends) and along the follow points from one to the next, a circle to either side - see-through beams with green arrows running along them - nothing hurts you at all, and what goes through you is not used up; where the rings go over such a place they are dimmed dark (not the circles and sliders themselves), the dim fading smoothly in and out with it, and so are the bullets in it. When an attack ends her white rings stop where they are and fade out there, harmless. Be on it when it is hit (on a slider: on its body) and everything within two circle radii of it - bullets and slices of beams - is cleared, with a green flash, and its ring goes out half as solid and harmless. In her spinners she throws six circles and sliders round her every eight beats, flying away from her; each sends out such a ring every two beats, half as solid and harmless while you are on it."),
            [BossMechanic.Kasha] = ("Round bullets.", "Every bullet fired in her section stops sixteen beats after it was fired and swells to three times its size (it hurts as big as it is); eight beats later it flies on the way it flew, shrinking back. For two beats before it swells a red circle as big as it will be flashes round it."),
            [BossMechanic.Komainu] = ("Curving beams: six at a time from her every four beats of her attacks, the first at you, each bending ever more, looping once round a small loop and flying out, fast; every second volley curls the other way. They hurt like a slider body.", "Every bullet fired in her section sets off at you twice as fast as it was fired and moves four beats that way without turning, stands four beats, sets off at you again, and so on, each bullet by its own clock, until her section is over or it has stopped four times (the stand as it is fired the first): then it flies on. Before every move a green arrow beside the bullet points at you."),
            [BossMechanic.Patrol] = ("Round bullets.", "No pauses. For eight beats every bullet that crosses the top or the bottom of the screen is caught there and laid into a dense, even pile along that edge, bullet against bullet. Then over four beats the top pile moves down and the bottom one up until they crash in the middle, and every bullet flies off away from the middle of the screen, drawing a narrow beam eight beats long behind it that hurts like a slider body. Red flashes along the top and the bottom warn of the piles a beat before they move, with Mokou's wall hit; they crash with the sound of Yuyuko's petals. For eight beats after that nothing is caught; then again."),
            [BossMechanic.Starlight] = ("Nothing of her own but her sphere of stars.", "No pauses; she stands in the middle of the screen. With the sound of petals flying off Yuyuko's tree she shoots small soft stars out, as Marisa's, that make a see-through sphere of lines round her, a star every 7.5 degrees along each line, its line from pole to pole pointing at you as it comes out; it turns slowly about that line, and the whole sphere spins slowly round her. Over sixteen beats it grows until its edge is just past the edges of the screen, it turns as big for sixteen beats, and over sixteen more it is pulled back into her; then at once it comes again, turning the other way (a shorter one fills the end of her section). With each another is thrown out of her at the same time, its stars white, turning the other way, that never comes back: it grows on until it is wholly past the screen. Their stars hurt like a slider body."),
            [BossMechanic.Wind] = ("Fans of ten orange maple leaves, 60 degrees wide at you, every beat, from wherever she is; they pull towards you, as Chen's arrowheads do.", "No pauses. She dashes in straight lines from edge to edge of the screen, eight times as fast as Mokou jumps, setting off on the half beats, each time along the line through the most bullets; a see-through beam shows it for about a beat before she goes. Behind her a beam stays for eight beats and hurts like a slider body. Every bullet she passes comes apart into two black feathers with thin white rims that fly straight out to both sides of her way, twice as fast, turning round as they go, the two of a bullet opposite ways."),
            [BossMechanic.Keyboard] = ("Her spiral of stars.", "Every circle and slider of her section comes again four beats later, in her red, twice as far from the middle of the playfield (but still on the screen), its approach twice as long, and shoots again with half the bullets and half the beams."),
            [BossMechanic.Vampire] = ("Her spiral of stars.", "In her section every slider shoots a beam instead of bullets, and every circle a ring of six straight beams, four beats long, the first at you. Every one of those beams that leaves the screen altogether shoots a fan of four half-size basic bullets, 120 degrees wide, back in from where its end left."),
            [BossMechanic.Staff] = ("Every four beats she lays out a ring of fifteen straight beams, four beats long, from her outward; each stands where it is laid, twice as big and twice as thick, until it is all there, then flies out as one piece, spinning round its own middle - every next one the other way round.", "Every slider's beam (also one that a boss lays out from her) stands still where it is fired, twice as big and twice as thick, for four beats after it begins; then it flies off as one piece, spinning round its middle (every next one the other way round), back to its own size; a slider's beam that is on the screen as her section begins spins from then on too. Gold arrows at either end of her spinning beams, held or thrown, show which way they turn."),
            [BossMechanic.Curse] = ("Every half beat two curses - the character 呪, white, glowing - one to her left and one to her right; for eight beats each speeds up and turns towards you, then flies on straight. Its ink hurts like a slider body.", "Every slider of her section throws a curse at you instead of its beam, as big as the slider is long, and every ring of the map's bullets in her section is laid out as 呪 (forty bullets at least)."),
            [BossMechanic.Surprise] = ("Six very dense spirals of basic bullets.", "The circles and sliders of her section turn round the middle of the playfield, every first one clockwise and every second the other way round, so that they stand where the map has them when they are due, each turning with it as one piece. Each stays eight beats after it is over, still turning, red or blue, hurting like a slider body, and shoots the bullets it had one at a time over those eight beats, straight out from the middle, instead of all at once. An arrow beside each, red or blue, shows which way it turns, and fades a beat after it has come. Her umbrella, small, turns slowly in the middle all the while and hurts like a slider body."),
            [BossMechanic.Thunder] = ("Every two beats a ring of five basic bullets, twice as big, straight out from her.", "Every ring in her section - the circles', the sliders', hers - is five bullets joined by straight gold beams as a five-pointed star that grows as they fly out. Every four beats half the stars hurt like a slider body and the other half are see-through and harmless, then the other way round."),
            [BossMechanic.Sword] = ("In the second half of every sixteen beats she stands and shoots a fan of five basic bullets, 40 degrees wide, at you every quarter beat.", "No pauses. In the first eight beats of every sixteen she dashes after you three times, as Elly does, each time straight into where you were, at half the speed she had, with Kagerou's swing; behind her a thick beam stays where she went and hurts like a slider body. When she slides again (or her section ends) those beams go: every circle radius along them a ring of five small basic bullets flies out."),
            [BossMechanic.Statue] = ("Every eight beats a big stone ball that homes on you for eight beats, then flies on straight; every two beats of its homing it shoots a ring of ten basic bullets.", "No pauses. Every bullet of her section starts at a quarter of its speed. Every four beats she sends out a fast wave, like Raiko's ripples; every bullet it goes over (also one fired before her section) flies on the way it went at twice the speed it had. The waves do not hurt."),
            [BossMechanic.Jealousy] = ("Every eight beats of her attacks three big green balls in a fan at you, each leaving Yuyuko's flowers scattered round its way, as small as her tree's, one every quarter beat, that stand for eight beats (their petals hurt) and then fly apart as the tree's petals do: three of each out, two falling.", "Her see-through clone stands in the middle of the screen and shoots an arrowhead at you every beat; every arrowhead that leaves the screen fans seven half-size basic bullets back in from where it left, 120 degrees wide."),
            [BossMechanic.Gatekeeper] = ("Every beat a ring of basic bullets out of the edge of her magic circle, body against body, every fourth left out; every second ring is turned half a gap round.", "Every bullet of her section flies twice as fast right by her and slows evenly to a quarter of its speed at the edge of the screen. Every sixteen beats, after a see-through preview of four beats, two thick beams come out of her at once, one to each side of the line from her to where you were when the preview came, with the Master Spark's sound and a shake; over eight beats they close in on that line, which does not move, until each is three degrees from it, then fade. They hurt like a slider body, and she stands still while they are there."),
            [BossMechanic.Bamboo] = ("A ring of thirty talismans every two beats.", "No pauses. Every sixteen beats 36 beams as thin as a slider's from where she is out past the edge of the screen, evenly round her, with you in the middle of a gap: a see-through preview for eight beats while she stands still, then they are there at once, with Byakuren's beam sound, and hurt like a slider body for eight, staying where they were shot while she moves on, and fading out as the set ends. Every bullet of her section, by its own clock, moves twice as fast 45 degrees to the left of its way for four beats, stands four, moves 45 degrees to the right of its way for four, stands four, and so on; for two beats before each move a red arrow beside it points the way it will go."),
            [BossMechanic.Myoga] = ("Every quarter beat a Marisa's star comes out somewhere in her magic circle, stands two beats, then flies off along the line from her to you, parallel to it.", "Every bullet that goes out of the top of the screen comes back down from there, straight down; every bullet that goes out of the bottom leaves a talisman behind, flying straight at where you are then, never turning."),
            [BossMechanic.Satellites] = ("A ring of ten big balls, an osu! circle each, every eight beats.", "No pauses. The bullets of her section fly the slower the bigger they are: a basic bullet twice its speed, one twice as big at its own speed, and so on. Every bullet at least twice as big as a basic one grabs the smaller ones that come within an osu! circle of it: they go slowly round it (once in eight beats), each on a tilted circle of its own as far out as it is big and an osu! circle more, as an atom's electrons do, wherever it goes (twelve at most); when it is gone they fly off the way they were going."),
            [BossMechanic.Hare] = ("Rings of ellipses, twice as often as stars would come.", "Every thirty-two beats four big beams from her, two to her left and two to her right, an X round the line to you: a see-through preview for two beats, then they come with Byakuren's beam sound, and over four beats the two of each side turn and slide out into one beam three circle radii to her side, along that line - two parallel beams across the whole screen with her between them. They are solid sixteen beats in all and hurt like a slider body; she stays where she is until they are gone."),
            [BossMechanic.Psychokinesis] = (stars, "Every sixteen beats a huge beam, four times as wide as Matenshi's, comes down from the top over where you are: a faint see-through preview as wide as the beam for four beats, with an impact frame over its last moments, then it glows, the screen dims round it, and the Master Spark's sound and a shake go on while it is there. It drifts slowly towards your side for eight beats, then explodes into 192 of Marisa's stars, violet as the beam, thrown left and right, with Suika's impact frame. It hurts like a slider body."),
            [BossMechanic.Citrus] = (stars, "She stands in the middle, and everything of hers turns slowly round it. In her warning a big orange, four osu! circles across, grows there and stands eight beats; then it splits into its ten slices, which fly straight out past the edge of the screen and come back, again and again, forming the orange whenever they meet. While they fly out a second orange grows and splits as they turn back, so one orange's slices always come back as the other's go. Red arrows on the slices show the way two beats before every split. The slices hurt like a slider body."),
            [BossMechanic.Pinwheel] = ("In her attacks each of her four points lets out a pair of her bullets every quarter beat, curling into arcs; every eight beats a ring of ten big, glowing arrowheads, one at you, that fly straight and let basic bullets out to their left and right all the way.", "Four points turn round her, red, yellow, green and blue, once every eight beats. Every bullet fired in her section comes out of one of them instead of where it was fired, two side by side, in the point's colour, flying off sixty degrees from straight out the way they turn: one pair after another, so that the streams curl into arcs round her that miss her middle."),
            [BossMechanic.Cubes] = ("A ring of twenty-four arrowheads every beat, each ring flying off its own way, opening out to three circle radii and closing in to its middle again every eight beats, the arrowheads turning round as they go, every ring one way or the other.", "No pauses. One giant lattice of cubes in beams after another, over the whole screen, standing where she was: see-through and harmless for four beats, then solid from its middle out over eight beats, with Byakuren's beam sound, then gone again from its middle out over the next eight, as Mai's snowflake goes. Where it is solid it hurts like a slider body."),
            [BossMechanic.Space] = (stars, "In her attacks the Earth seen from orbit lies over the whole screen, see-through, with the sound of Yuyuko's tree. All through her section many small asteroids fly slowly across the screen from every side, every one its own size, way and speed, and every bullet that flies into one bounces off it; they do not hurt. As each attack begins a satellite comes in slowly from behind her, out of the screen, and flies on straight across the line from her to you until it has left the screen, drawn over its beam; every four beats it starts turning, evenly and very slowly, to face you again (when it turns the other way than it last did, its grid flashes). Every sixteen beats it fires a big beam both ways, ahead and behind, narrow where it leaves it and widening as Marisa's, after a see-through preview of four beats, solid for eight with the Master Spark's sound and a shake. A square grid of beams goes with it, turned with it, see-through and harmless - but every eight beats it sends out a thick grey wave with Byakuren's beam sound, and the grid is solid under the wave. Solid, the beam and the grid hurt like a slider body."),
            [BossMechanic.YinYang] = (stars, "Every eight beats, once her last throw is back, she turns into a yin-yang orb as big as her magic circle and throws herself at you (she glows red first): it ricochets twice off the edges of the screen, flies straight back to where it was thrown from and is her again. The orb hurts like a slider body, and every bullet that flies into it bounces off it. With other bosses on the screen she throws them instead, all at once, and they keep doing what they do; one whose own mechanic is moving her is left alone."),
            [BossMechanic.EvilEyes] = (stars, "She stands at the top in the middle, with five big eyes at the corners of a pentagon below her, joined by lightning that does not hurt. Every second bullet fired in her section is shot again from one of her four lower eyes at you, each eye its own kind: basic, arrowhead, ellipse, star. Every slider's beam comes from her, one beam at you, as Junko's do. Every sixteen beats every eye flashes white for two beats, then strikes a big bolt of lightning a way of its own, twice as thick as Tojiko's, with twice as many branches, twice as long, hurting for two beats. Every circle hit and slider over is thrown at you from her eyes in turn, golden, falling as Urumi's do."),
            [BossMechanic.BigBat] = (stars, "Every twenty-four beats she flashes red for two beats, then turns into a big bat and chases you for eight beats as fast as Koakuma's bats fly, hurting like a slider body; every bullet she flies through is taken into her magic circle. Then she stops and for eight beats her circle shoots what it took at you one after the other, side by side, all the way from her to you as she stopped: twice as fast and twice as big as they were, red, each with a beam behind it four beats long that hurts too."),
            [BossMechanic.AngelOfDeath] = (stars, "In her attacks she shoots a ring of ten bats every eight beats: Koakuma's bats, half as fast and homing half as hard, gone after sixteen beats. Every beam of her section that leaves the screen lets one of Koakuma's bats in where it left. Every bat shoots a basic bullet at you every beat. Every eighth bullet that leaves by the bottom comes in again at the top, half as big, three times in all (and from the top to the bottom). After her last section everything turns dark purple, the screen dims for eight beats, and two beats later everything, bullets and beams, turns at you once, warned of by red arrows beside every bullet."),
            [BossMechanic.Underworld] = ("Rings of 36 waving beams.", "She always stands in the middle. In her attacks everything flies straight out from the middle, bullets and beams, and what is fired too; big red arrows round her warn of it two beats before. Every four beats of an attack a ring of 36 beams waves out of her as Shou's do, hurting like a slider body. Every fourth bullet that leaves the screen is shot again from her at you."),
            [BossMechanic.Sweep] = (stars, "Every sixteen beats an endless beam as thin as a slider points up from her, see-through for four beats, then sweeps once round her in four beats with the sound of Byakuren's beam and fades. Every bullet in its way is cut in two, the halves flying apart square to the beam."),
            [BossMechanic.Distance] = (stars, "She goes for a beat and stops for a beat, in turn. As each stop begins she throws an arc at you with one of Kagerou's swings - Elly's arc, half as big - that flies on until it has left the screen, hurting like a slider body; every bullet it goes over is cut in two, the halves flying apart across it."),
            [BossMechanic.WellBucket] = (stars, "Everything fired in her section comes from the top of the screen, above where it was fired, and falls. She stays at the top, her magic circle touching it, going along it over you. Every four beats she stops for two: three thick beams straight down from her show see-through for a beat, then hurt for a beat."),
            [BossMechanic.KnifeTrail] = (stars, "Every twentieth bullet fired in her section is twice as big and leaves a knife behind it every half beat while it is on the screen; each knife stays where it was left for eight beats, then flies at you."),
            [BossMechanic.Poison] = ("Streams from all round her magic circle, twice as fast.", "Two bullets that touch each other are both gone, and a small flower of five of Yuyuko's pink petals bursts where they met. In her attacks twelve streams come out of all round her magic circle, turning slowly, twice as fast as bullets."),
            [BossMechanic.Mining] = (stars, "In her attacks she throws a block of stone as big as an osu! circle every half beat: it lies on a grid along the walls of the screen - the cells against the walls first, then the ring inside them - and hurts like a slider body until her section is over. In her pauses a big centipede comes in from behind the wall at her back (a red arrow shows where, a beat before), charges across at you and out of the screen, hurting like a slider body; every block it goes through bursts into a square of twenty bullets."),
            [BossMechanic.Spoiler] = ("Nothing but her photo frames: they do not hurt.", "No pauses. Every four beats she throws a photo frame at where you are, held square to the way it flies, four circles tall, shrinking to two as it gets there four beats later - only its rim; its see-through grey glass comes with the flash. Then she takes the picture: every bullet in the frame turns to fly the way from the frame to you, half as fast, and the frame stays there with its glass for two beats. If you are in the frame you are hit, and for two beats your character follows where your cursor was four beats before."),
            [BossMechanic.Creation] = ("Nothing of her own: everything that is fired comes out of her wings.", "No pauses; she stands at the top of the screen in the middle, as Kaguya does, with three pairs of white wings that sway a little. Every bullet fired in her section comes out of the middle of her wings instead, four times, of four wings in turn, at the speed it had: each wing lets them out one after another as a dense stream that turns round once every eight beats, every second wing the other way round. Every laser of her section is fired again from one of her wings, the six in turn, straight and four times as long, its first beam at you as it starts. Her wings do not hurt."),
            [BossMechanic.Mirage] = ("Fans of three big balls, two circle radii each, 120 degrees wide at you, every four beats; they hurt like a slider body.", "No pauses. Every 16 beats a golden beam six circle radii wide along the line from her to you across the whole screen: eight beats a see-through preview, then it widens from its middle line and hurts like a slider body for eight beats, and fades. While it hurts, every bullet that leaves the screen (not her own) comes back in where it left, flying straight at the beam, square to it; what leaves the screen during the preview is held where it left and all comes back in that way as the beam turns solid, flashing gold there for a beat before."),
            [BossMechanic.Effigy] = ("Nothing but her dolls.", "No pauses. Every eight beats she throws a fan of ten small dolls, 150 degrees wide round the way to you, more than twice as fast as bullets; they hurt like a slider body. Every bullet a doll touches is shot again from the doll at you, three times as big, with a flash. Two such bullets of two different dolls that touch bounce off each other, once each."),
            [BossMechanic.Fossil] = ("Two grids of small ellipses, half the size they were, half as far apart: every two beats a row across the whole screen comes down slowly from the top and a column down the whole screen comes in from the left, every second one half a gap aside; each bounces once off the bottom or the right and flies back, and they never stop.", "No pauses. Her section goes in stretches of 16 beats. When one begins everything that is flying (but her grid) stops, grey, until it ends (what stopped in the stretch before flies on). Every circle and slider that is over in a stretch stays where it is, grey and still, harmless, and shoots nothing; when the stretch ends, after a big white flash, all of them shoot what they held at once - bullets and lasers - and go. Doremy's and Sagume's copies are held too."),
            [BossMechanic.Frog] = ("Slices of beam. Every slider of her section is a sliderwhistle, but its laser is fired from her, along the slider's path, half as many beams as Junko's in a fan 120 degrees wide round the way to you, one and a half times as fast; they bounce once off the border of the screen.", "She stands where bosses stand, not in the middle. Every slice of a beam is see-through and harmless for its first four beats. Every 8 beats she shoots every fourth bullet that appeared in them out again, in five fans of 120 degrees at you, one after the other, half a beat apart."),
            [BossMechanic.Necromancy] = ("Talismans in ellipses.", "Every second bullet that leaves the playfield turns back: it flies the way it came at a quarter of its speed as a paper talisman, with the bullet itself under it, brown and harmless, and fades out after sixteen beats."),
            [BossMechanic.Prism] = ("Triangles of plain bullets.", "A big prism turns in the middle. Bullets that cross it turn along its side, and leave mirrored and split into seven small rainbow bullets, each with a narrow beam all of its colour behind it, two beats of its way long, that follows it out of the screen and hurts like a slider body (every second bullet of a ring leaves whole, as it went in). The prism hurts."),
            [BossMechanic.Recollection] = ("Hearts, as Koishi's: twice as big, twice as many in every ring (in a spinner too).", "Every two beats she reads which way you moved (three eyes open round you before each reading, the first in front of you); bullets in the cone of 90 degrees of any of the eyes, within five circles, turn red and slowly turn to fly straight at the line you traced, perpendicular to it. You leave a red beam behind you: each slice of it is see-through and harmless for 4 beats, then hurts for 8 as it fades out - stand still and it catches up with you."),
            [BossMechanic.Qi] = ("Fans of plain bullets aimed at you.", "No pauses. In pulls of sixteen beats she draws in every bullet near her, even other bosses'; they are fed into one big growing ball (as big as all of them together, twice as fast as their average, as coloured as their average) and fly on through her, never fed again; every second bullet is left alone. When the pull ends the ball is thrown at you and the next pull begins at once; on its way the ball feeds on every bullet it touches, which flies on, and grows. No ball's radius grows past 1.2 times the playfield's height. When its middle reaches a wall it sends out five rings of sixteen bullets from its middle, like Mokou's ball, and ricochets; at the next wall it impacts again and fades out."),
            [BossMechanic.Smoke] = (stars, "In her attacks she throws a ring of smoke clouds every eight beats. Bullets inside smoke are half transparent (not the other bosses' own things, like Yukari's trains), twice as big and hurt like a slider body. The smoke itself does not hurt."),
            [BossMechanic.Volley] = ("Arrowheads that fly straight.", "A quarter of the bullets per ring, but each is shot three times in a row, with more bullets beside each shot."),
            [BossMechanic.Death] = ("Plain bullets.", "No pauses. Every sixteen beats a grey ripple stops everything it passes (a beam whole, never only part of it); eight beats later it all falls as it is and darkens as it falls. A giant skull shows over a dimmed background."),
            [BossMechanic.Spring] = ("Rings of flowers that burst into petals. In a spinner they have half as many flowers, and come half as often as the spiral's shots.", "Branches grow from the four corners of the screen, always at the same speed (a short section only grows them part of the way). In her attacks bullets that leave the screen at a side grow flowers on the branches, evenly spread (half as often as Yuyuko's, as fast); eight beats after it appeared, each flower bursts into petals (small ones, as big as the petals of Yuyuko's tree, like the petals of her own flower bullets). In her pauses no new flowers grow, but the ones that are there still burst on time."),
            [BossMechanic.Momentum] = ("Rings of ellipses.", "No pauses. Every eight beats a push is announced: for four beats everything on the screen glows, turns light grey and shakes, and every eighth bullet swells to one and a half times its size. Then everything gets extra speed away from her, towards you, which adds up with every push. Every circle that is hit and every slider that is over gets a grey combo colour, glows a little and falls on you, darkening as it falls like Zanmu's bullets (a slider keeps its shape); after a moment they hurt like a slider body, circles too."),
            [BossMechanic.Inchling] = (stars, "In her attacks every bullet and beam, hitbox included, is half its size at the edge of her magic circle (and inside it) and grows gradually to one and a half times its size at the edge of the screen, glowing more the further it is. During the warning before an attack the sizes change to that and everything shakes; they change back after it. A wall sound plays at every attack."),
            [BossMechanic.Cloud] = ("Nothing of her own: the hands of her cloud do the hitting, and their walls and claps send out the rings.", "The cloud Unzan's head stands behind her (as seen from you) and faces you, with a hand on each side of her. In an attack every 8 beats one of its hands (left, right, left...) is first drawn slowly back, then thrown at you along an outer arc, speeding up; where it hits a wall far from her (never the two walls behind her) it sends out Mokou's rings, shakes the field for 4 beats and sounds like Hecatia's Moon, stays for two beats and comes back in a straight line. Hands that are home swing a little, slowly. During the warning the head grows and the hands fade in close to it and move out to their places; it all goes the other way when her phase is over. In a pause both hands slowly come together on the place where you were when they set off (and hurt there as they meet) and send out four rings of ellipses shaped like an arrowhead bullet (sharp tip, arc sides), with the same shake. She has only one warning, the one that brings Unzan in; the hands hurt while they are out, and a throw is never cut short: if her phase ends meanwhile, the hand still lands, stays and comes home before the cloud goes. A hand that is out swallows the bullets it touches (unseen) and shoots them all out at its next wall hit (or clap) as five rings, one right after the other, each spread evenly over 180 degrees away from the wall (at a clap: towards you)."),
            [BossMechanic.Silence] = ("Only rings of arc beams: every two beats a circle made of 10 arcs with wide gaps between them flies out from her, also in a spinner.", "In her attacks every hitsound is muted, the circles and sliders are hidden as with the Hidden mod, and bullets (their edges too) and beams get blurrier and glow more the further they are from her (what is inside her magic circle is normal; the hitboxes do not change). The outline of every slider then turns into a beam that grows outwards from it, all round it, until it has left the screen, in 20 pieces with gaps between them; it hurts like a slider body."),
            [BossMechanic.Scrolls] = ("When an attack begins, five beams as thin as a slider's start from round her, away from you, and home in on you like Sekibanki's heads. In a spinner five thin beams point outwards from her and spin.", "She remembers where every fifth circle and slider of her section starts (Doremy's and Sagume's copies too), up to 5 places at a time; 32 beats later a big star flashes up there for a beat (it hurts to touch) and five such beams start from round it, at least 2 beats after the place before. Her beams are as wide as a slider's and fast, with a star at the tip, and home in only for their first sixteen beats, then fly straight; like Koakuma's bats, a beam stops once it has been within two circle radii of you for eight beats in all, or has left the playfield after its homing is over; every part of it is there for 4 beats, narrowing away over the last two, so a beam ends in a point; while a star of hers is outside the screen a red arrow glows at the wall nearest to it, points at the wall, goes along with the star and grows as it comes nearer. Every fourth ricochet star fired in her sections has a beam for a tail, eight beats long. Her beams do not shake the screen."),
            [BossMechanic.Dream] = ("Plain bullets in two chains of three-bullet rings that turn opposite ways. No beams.", "No pauses. Every circle and slider has a dark blue copy mirrored through the middle of the playfield. A copy shoots what its original shoots, mirrored, with half as many bullets, three quarters as big and twice as fast, white and blue, glowing; so do the spinner's stars. Five white bullets stay inside each copied circle and fly out of those very places as it is hit (a slider's as its head is)."),
            [BossMechanic.Heads] = (stars, "Every eight beats of an attack she throws one of her heads away from you; it turns back and chases you like Koakuma's bats for 64 beats, then fades. The head and the beam behind it (twice as wide as a slider's) hurt like a slider body: every part of it stays where the head was for 16 beats, then flies off the screen."),
            [BossMechanic.Rewind] = (stars, "No pauses: as soon as one of her attacks ends the next begins, and the one that ended is played again backwards over it: every circle and slider of it comes back white where it was, the last one first (sliders the other way along their path). They hurt like the originals and shoot what the originals shot the same way, white, with a quarter as many bullets, one and a half times as big and half as fast."),
            [BossMechanic.Return] = ("Paper talismans in rings shaped like a pentagon.", "With other bosses on the map she does what they do herself, with half their bullets and beams: in a section of her own the last one first and so on backwards, for sixteen beats each after a gap of four; in a section she shares what the boss beside her does, four beats later. Alone every second bullet that goes out of the screen in an attack is shot again from her instead, half as big and half as fast, towards the place where it left, and every slider's beam that reaches the edge is copied from her, half as wide."),
            [BossMechanic.Miracle] = ("Rings of thirty small ricochet stars in the shape of a star, each turned a little further, every second the other way.", "In her attacks every ring has twice as many bullets, half as big, and the round rings are five-pointed stars; the background turns a dim green with a giant faint star behind it."),
            [BossMechanic.Blades] = ("Rings of knives with long blades.", "In her attacks the bullets of every fifth circle or slider come out in a ring round where you are, fading in, and slowly fall away from it towards you. Four of every ten slider beams stop when their slider ends, turns to point at you while it straightens into a line, and four copies grow out of it to their places very far apart; then the row turns as one until its middle beam aims at you, flashes, and all five are thrown that way side by side, parallel."),
            [BossMechanic.Traps] = (stars, "Every sixteen beats she puts three bear traps down where you are, two beats apart, each with an approach circle. When it has closed the trap is set with a thud. Step into one and it snaps shut: it hurts and holds you where you are for two beats, with a red glow round you. One nobody steps into snaps shut by itself 32 beats after it was put down. At most 6 traps on the map; the oldest fades out."),
            [BossMechanic.Haste] = ("Basic bullets in double rings.", "No pauses. Every ring is shot twice, right after each other; every bullet on the screen, whoever fired it, speeds up, more and more, to two and a half times its speed by the end of each of her long attacks; every fourth bullet is a little bigger and every fourth beam twice as thick; every beam speeds up too, and everything turns gold-brown, more and more. Meanwhile the background dims grey, the bullets blur towards the middle of the screen, speed lines come in from the edges, and a riser climbs to its highest right as the attack ends."),
            [BossMechanic.ImpossibleRequests] = ("Every two beats a ring of twenty bullets followed by three more, half a beat apart, each turned a little further than the one before, so that they spin; in a spinner too.", "She stands at the top of the screen and never pauses, under a giant moon that comes slowly down in a dark blue sky. Every fourth bullet that leaves the top falls back as a star, three degrees to the left or to the right of straight down, leaving a beam behind it that narrows to a point, whose slices live for four beats. Slider beams that leave the top fall back in short purple pieces. Every ring fired in her sections turns the other way from the one before. Eight beats after the last boss section she comes back until the song ends (with Mokou on the map both of them do): slices live for eight beats, every second bullet falls, bullets change between ellipses, stars, talismans and all three mixed every four beats, and every twentieth is three times as big."),
            [BossMechanic.Rays] = ("Every four beats sixteen big glowing bullets fly at her from outside the screen, the first from behind you.", "She stands in the middle and never pauses. Every eight beats the thirty 3 degree cones from the middle of the screen to its edge that hold the most bullets light up, and the bullets in them glow and are pulled to her. A cone comes up faint and grows clearer over its first six beats; the cones brighten for two beats and after eight turn into bright beams for four, hurting like a slider body, while the screen dims; as they fade, what was pulled in comes out of her as five even rings. When her section ends she stays where she stood until her last beams and rings are over."),
            [BossMechanic.Slash] = ("Rings of straight beams that fly out of her, all the time, in a spinner too.", "In her attacks she watches every sixteenth bullet; every two beats thirteen thin slashes go through them, two by two, spread as widely over the screen as the bullets allow, leaving out what is at its edge, across the whole screen, see-through and harmless for four beats, then solid and twice as thick for two, hurting like a slider body, before it fades. As a slash turns solid it cuts the bullets across it in two along it: one part flies on the way it was going, the other the opposite way. Where it crosses a slider's beam it pokes a hole in it, and the slices fall like petals."),
            [BossMechanic.Verdant] = (stars, "In her attacks the background dims dark warm green and every bullet turns green, a quarter bigger, and glows. What is fired meanwhile hurts like a slider body and goes round once: when it leaves the screen it comes in again on the same line from the opposite wall, and is gone the second time it leaves. Those bullets cannot be destroyed: what would take one away only gets a copy of it, and the bullet flies on. A bullet that has left the screen has lost her buff: it comes in again its own size and colour, without the glow, is used up by a hit and can be destroyed."),
            [BossMechanic.Tide] = ("Hollow bubbles, a quarter as many as a boss's stars, all through her section (in a spinner the spinner's stars too): they hurt as bullets do, and each pops into a ring of eight bullets sixteen beats later.", "In her attacks the screen dims ocean blue and bullets and beams turn blue, and what is fired swims from side to side by a circle radius (not the rings Junko shoots out again), and hurts like a slider body instead of being used up by a hit. In her section the sliders fire no beams. Every sixteenth bullet is a hollow bubble twice as big: it hurts as a bullet does, and sixteen beats after it appeared it pops into a ring of eight bullets half as big as it was, flashing red for the last four. Every eighth bullet that goes out of the bottom grows a blade of dark green seaweed there over two beats, each its own height between an eighth and three eighths of the screen, with a sharp tip, that sways, hurts like a slider body, and after eight beats comes off the ground and falls upwards. Six green petals grow on every blade, and they hurt while they are on it too; as it comes off the ground they spread away from it as petal bullets that flutter as they fly. Every bullet that swims leaves a trace of beam behind it, following its way for two beats, as wide all along, that hurts like a slider body."),
            [BossMechanic.Storm] = ("Lightning at you, every four beats of an attack, which stays the way it was aimed; see-through and harmless at first, as every bolt is.", "The screen dims dark grey and heavy thunderclouds hang along the top, over the lightning and the rain, flashing where a bolt starts. Every bullet that goes out of the top falls back where it left as a bright ellipse half its size, never dim. Every two beats a jagged bolt of lightning, glowing, all of one piece with its branches, grows from the top to the bottom, with thin, fainter branches and smaller branches that narrow to a tip, light blue at first, white and half again as thick once it is solid; it is see-through (faintly) and harmless for eight beats, then solid for four, hurting like a slider body, and bullets near it are dim; every second bolt thunders, heard only while it is solid. As a bolt turns solid, five small bullets of its colour fly back from where it ends, spread over 120 degrees, never dim. In a spinner the clouds are in the middle, and ellipses and bolts go from there outwards."),
            [BossMechanic.Possibility] = ("Nothing but flowers of beams: every two beats a five-petalled flower grows out of where she stands, every petal two smooth arcs that meet at a sharp tip, with gaps between the petals, and hurts like a slider body.", "In her attacks every tenth bullet on the screen has a beam for a tail, four beats long, that flies along with it. A big bright red flash warns of her pauses: in them everything, bullets and beams, is pulled straight away from her, hard, a big grey wave goes out from her, and the screen shakes."),
            [BossMechanic.Stacking] = ("Rings of ellipses.", "Every four beats every bullet on the screen gets as much speed again at right angles to the line between it and her: clockwise within one circle radius of her, anticlockwise within two, clockwise within three, and so on. In her attacks bullets whose bodies touch stick together, body against body, up to eight in a clump, each swelling to twice its size as it joins, and fly on as one, half again as fast as the law of impulse says (never slower than half again the fastest of them)."),
            [BossMechanic.Foxes] = ("Rings of eight talismans that start twice as fast as usual and slow down to a quarter of their speed a playfield's length out.", "When an attack begins, and every eight beats of it, eight beams grow fast out of where she stands along golden spirals, each such fan on its own; where they start stays where it is. Once all eight have passed the edge of the screen they go from the end they started at, as fast as they grew. All that time, while they grow too, a bullet that crosses one bounces off it, twice at most. While they grow, their tips cut the bullets on their way in two along the spiral: one part flies on the way it was going, the other the opposite way. The beams hurt like a slider body."),
            [BossMechanic.Drift] = (stars, "Everything fired in her section loses speed the nearer it gets to the wall ahead of it, down to a quarter of its speed at the wall. When a pause starts a ship comes at you, bow first, ten circle radii long, out of the wall nearest her from behind her, fast, and four more with it, two to each side, each a little further behind: all of them hurt like a slider body, and nothing stays in them: every bullet that gets into one slides out to its nearest edge, fast but smoothly, and is turned once to fly straight out of the ship, and the beams bend round them as they go by."),
            [BossMechanic.Misfortune] = ("Talismans in hexagons; one that goes out of the screen comes back in the way it came, once.", "Every eight beats every beam on the screen turns dark blue and flies back the way it came, and every bullet that has not been copied before leaves a dark blue copy of itself flying back the way it came while it flies on (a bullet is copied once at most; the copies are never copied). For the four beats before that, small red arrows of Seija's dress, not see-through, flash beside the bullets that will be copied, each pointing the way its copy will go."),
            [BossMechanic.Market] = ("Every four beats, every two in a spinner, a ring of talismans five circle radii round you closes in slowly on where you are.", "Every eight beats two walls of big talismans come in slowly, at half a plain bullet's speed, side by side with no gap between them, from the top and the bottom, the next time from the left and the right. A talisman of a wall that comes within four circle radii of you turns into a small knife with a blue handle, stops its flight and creeps at where you were at a quarter of a plain bullet's speed, so the walls part round you and the knives pile up."),
            [BossMechanic.Judgement] = ("Very dense rings of talismans.", "When an attack begins (after big red arrows round you have pointed in at where it will be for two beats) a magic circle, 4.8 circle radii from its middle to its edge, is placed round you and stays where it is, and another as big where it is mirrored through the middle of the screen. You can be in either of them but cannot leave them, by any way of moving: you stay on the border of the nearer one at most (with the cursor you jump across to the other when it is nearer). They do not hurt. Whatever enters one of them, bullets and beams, turns to its middle at half its speed, flies on through, and has its speed back when the circles are gone. Bullets outside the circles are dim. The circles fade out in the pause."),
            [BossMechanic.Claws] = ("Rings of bright white bullets, twice as fast as any, every half beat as she flies at you, and as fast as any, every beat, while she stays.", "No pauses. When her section begins, and every sixteen beats, she howls and throws herself as fast as Chen at where you were at that moment, and stays there for eight beats. All that time, every beat, she claws at you: three thin arcs side by side round her, as far from her as you are, so they reach anywhere, turned 45 degrees round you clockwise and the next one as far the other way, so they cross like her swings. A claw, narrow, grows faint and harmless from one tip to the other in half a beat and stays so; two beats after it began it lights up in a quarter of a beat (every second one with a swing), hurts like a slider body for a beat and fades out. When it lights up it cuts whatever is in it at that moment in two along the arc, bullets (never more unevenly than 8 to 2) and beams (never more unevenly than 20 to 1; not Marisa's), but not the objects of the bosses: one part flies on the way it was going, the other the opposite way."),
            [BossMechanic.Reaping] = ("Bats like Koakuma's that do not home, a lot of them, all round her: twice as many as a boss's stars, flying until they leave the screen.", "No pauses. She slides fast after you until you are within reach of her scythe, half the playfield's height long, and on the next mark of two beats stops for a blow. The warning: a thin arc round her at the scythe's reach, faint and harmless, grows from tip to tip as fast as it will light up, and stays so until two beats after it began. The blow: the arc lights up very quickly from tip to tip the way it grew, and she stays where she is until it is all lit. What has lit up hurts like a slider body, four beats from the start of the blow; close to her you are under it. When it lights up it cuts whatever is in it in two along the arc, bullets (never more unevenly than 8 to 2) and beams (never more unevenly than 20 to 1; not Marisa's), but not the objects of the bosses: one part flies on the way it was going, the other the opposite way."),
            [BossMechanic.HalfMoon] = ("Stars with tails of beams, four beats long, that narrow to a point.", "No pauses. Every sixteen beats a giant crescent moon appears on you, its back to the outside of the screen: white with a thin grey outline and a soft glow, see-through and harmless at first, it grows from one tip to the other over four beats while the screen shakes. Then it lights up the same way round and is solid for eight beats: it hurts like a slider body, and everything that flies into it, bullets and beams alike (not Yukari's train), bounces off it once, with a flash where it does. Before it goes its glow flashes; then it fades out while stars with short tails fly off all along both its edges, and as it starts to fade its body shoots out eighty white stars from all over it, each a way of its own, at half their speed. A moon always goes through to its end, also after her section: she stays until it is over. The next moon grows the other way round."),
            [BossMechanic.Earthquake] = ("Ricochet stars.", "Every sixteenth bullet that goes out of the bottom of the screen is shot back up as three bullets half its size, fanned out over 120 degrees. Every eight beats she sends out a shockwave and the screen shakes for as long as it is on it; meanwhile every eighth bullet that goes out of a wall the wave has reached comes back in the same way."),
            [BossMechanic.Recording] = ("Four rings of plain bullets at once, each slower than the last.", "Every four beats of an attack everything within five and a half circle radii of you is recorded, and a bright circle, clear in the middle, fades in there: the bullets fly on, and each leaves a see-through preview where it was, in the colour of her hair (black with a violet sheen), wherever you go. Two beats later the previews turn solid and fly off, as big as the bullets were and the way they were going. Every slider's beam fired in her attacks is fired again four beats later from the same place."),
            [BossMechanic.Bloodlust] = ("Bats like Koakuma's that do not home, half as fast, and fly until they leave the screen.", "In her attacks three rings of uneven pools of blood with vampire's fangs in them turn round her, three, five and seven circle radii away, each ring the other way round. A bullet that touches a pool turns red and glowing, as at the end of Remilia's attack, and is aimed at you as you are at that moment; it does not turn again. The pools themselves do not hurt."),
            [BossMechanic.Shockwave] = ("Rings of plain bullets twice as big as usual.", "Every eight beats she stamps: the screen shakes and a smooth ring goes out from where she stands. A bullet it touches is thrown outwards, 2.5 times as fast right by her, less and less further out, down to 1.2 times at the distance of the wall, and it glows the more the faster it was thrown."),
            [BossMechanic.Fortune] = ("Golden bullets, a quarter as often as a boss's stars, each pulled gently the way she threw it, that bounce off every wall like a ball, twice, keeping 70 % of their energy, and then leave the screen.", "Every two beats every tenth bullet on the screen turns gold, glows and is pulled the way it was going (each bullet has its own gravity, which stays as it was), bouncing off any wall of the screen like a ball, twice, keeping 70 % of its energy every time, and then its gravity takes it out of the screen. In an attack the share grows from every tenth bullet to every fourth by its end, and starts over with the next attack."),
            [BossMechanic.Flowers] = (stars, "Every fourth bullet that goes out of the bottom of the screen grows into a sunflower there: the heads are alike, the stems all different, so the bottom of the screen looks like a field, swaying left and right. Only the dark brown head hurts, like a slider body. It flashes on the ground a beat before it comes out. After eight beats the stem shrinks back and the head flies up, five degrees to the left or to the right by turns, while its petals leave it as a slow ring of sixteen yellow petals."),
            [BossMechanic.Autumn] = ("Autumn leaves: orange maple leaves.", "In her attacks every second bullet on the screen turns orange, more and more. When a pause starts each of them is a leaf that stops and falls slowly, swaying, to the bottom of the screen, and there two leaves fade in for each, evenly spread. They turn slowly as they fall. After her next attack starts they fall upwards just as slowly, not all at once, five degrees to the left or to the right, half of them each way, each turning at a speed of its own."),
            [BossMechanic.Stampede] = ("Nothing but rings of beams, all the time, in a spinner too; they hurt like a slider body, and have gaps to slip through.", "Her attacks are like Remilia's: the rings on the screen get denser and turn further as an attack goes on, every fortieth bullet is three times as big and everything glows more and more, without the red. The background dims brown and a giant see-through horse's head shows through it. When an attack begins the line from her to you is taken, as with Zanmu's fall, and every bullet on the screen, also what is fired during the attack, turns that way; for two beats before, red arrows flash beside every second bullet, pointing along the line from her to you. Every bullet speeds up to 1.2 times its speed over an attack and slows down to its own again over the pause. Every four beats of an attack every fourth bullet on the screen shoots two bullets half its size, one to its left and one to its right."),
            [BossMechanic.Swarm] = (stars, "All through her section every fourth bullet on the screen, whoever fired it, is a firefly: twice as big, bright green, with bloom and a pulsing glow of the same green. It leaves its way, drifting on slowly and wandering restlessly from side to side, but not far."),
            [BossMechanic.Crescent] = ("Rings of arrowheads that fly straight.", "In her attacks every bullet on the screen, whoever fired it (the other bosses' own bullets that fly straight too), goes round twice as fast as it flies, at any distance, half of them one way and half the other, round where she stood when it was fired (what was on the screen already, round where she stood when the attack began): the middle of each stays where it is when she moves on. When the attack ends they fly on straight the way it left them. For two beats before each attack a gold arrow beside half the bullets shows the way each will go round her. Every fourth ring fired in an attack is three times as dense."),
            [BossMechanic.Destruction] = ("Knives, from her and from three clones that turn round her.", "No pauses. Every eight beats she puts three red eyes down where you are, two beats apart; four beats later each explodes, taking every bullet and every piece of beam within about 3.4 circles of it (and you, if you are there). Each clone shoots what was blown up again, one after the other, twice as fast and as big as it was, outwards from the eye; the new bullets glow and cannot be blown up. Every fourth one also sends four bullets out along the axes."),
            [BossMechanic.Anchors] = ("Nothing but her anchors: big silver anchors on chains of bubbles, one thrown at you every eight beats, in a spinner too.", "She stands in the middle and never pauses. Every sixteen beats she throws eight anchors round her, one every half beat, evenly round the circle. Each flies slowly to the wall in four beats, chained to her by a string of bubbles, and stops with its crown a little out of the wall with a heavy metal clang, which shakes the screen for a moment; it stays there for eight beats, and then it is unchained and slowly crawls on out of the playfield the way it flew, fading, and its bubbles pop one after another from her out to the anchor over two beats, each into a ring of six small bullets that spread away. Anchors and bubbles hurt like a slider body."),
            [BossMechanic.Orbs] = ("A yin-yang orb at you every eight beats, in a spinner too: one and a half times as big as Reimu's, it ricochets off the edges of the screen and off the other orbs, hurts like a slider body and is gone after sixteen beats.", "Every thirtieth bullet turns into one of her orbs where it is and flies on its way; at most twelve fly at once (the oldest shrinks away). In her attacks bullets whose bodies touch ricochet off each other, once each."),
            [BossMechanic.Fissure] = ("Every four beats she stomps: everything within eight circle radii of her is thrown on twice as fast, glowing like magma, with a narrow tail of beam two beats long, and bursts into two small ellipses at the wall. The stomp hurts you if you are in it, and jagged, branching cracks of magma in the ground round her hurt like a slider body for two beats. Every sound of hers plays twice at once.", "Every sixteen beats a wide, jagged crack of glowing lava, two circles across at her and narrowing like a branch of Yuyuko's tree, grows from her towards you and out past the edge of the screen over eight beats, many long branches with twigs of their own, ending in sharp points, growing out of it as it goes. It hurts like a slider body, branches too, and eight beats later it explodes in a flash of the World's Ender's impact frame (its stars flash on and round the crack for a beat before) into glowing magma ellipses off both its sides."),
            [BossMechanic.Scorch] = ("Every four beats five rings of five ricochet stars, from five places round her.", "In her attacks one beam comes out of her, twice as thick as a spinner's and widening as it goes, aimed at you, turning slowly towards you. Every slice of it goes out as far from her as you were when it was fired, and leaves a scorch mark there for sixteen beats that hurts like a slider body: a round spot of the beam itself, as wide as the beam was there, running into the beam without a seam. Marisa's big star is on her and her beam sound plays while she fires. When her attack ends, what is still flying goes on out to the edge of the screen."),
            [BossMechanic.Recall] = ("A fan of five knives with yellow handles at you every two beats.", "Every eighth bullet turns into a yellow-handled knife that stops and falls towards where you were, faster and faster. Everything that goes out of the screen is remembered sixteen beats at a time, and comes back in the next four beats as knives, in the order it left and four times as close together, each from where it left and straight across from that wall; in the beat before, every wall flashes gold."),
            [BossMechanic.Pagoda] = ("Every four beats a ring of sixteen long beams that wave slowly from side to side as they fly out, half a circle radius each way, slowly near her and faster and faster further out.", "She stands in the middle of the screen. A see-through preview shows her cross for two beats; then a thick, glowing cross of beams grows out of her past every edge, one seamless piece, and turns one way and then the other, changing at every second start or end of her attacks, flashing another colour in the beat before it turns the other way; it hurts like a slider body. Every fourth bullet fired comes out of the cross instead, spread evenly along its arms, flying straight across it to one side or the other."),
            [BossMechanic.Constellation] = (stars, "Every eight beats every four bullets on the screen that are nearest each other are joined by a thin silver beam into a constellation, which hurts like a slider body; only the bullets of the constellations stand still, for four beats, then fly on; what one lets go may stand in the next one. Constellations never overlap, nor cross themselves. For the four beats before (one at least for every constellation), the beams show see-through where the bullets will stop."),
            [BossMechanic.Icosahedron] = ("An arc of beam ten degrees wide at you every quarter beat, flying out from her.", "In every attack a giant icosahedron of beams (one for every edge) fades in round the middle of the playfield, turning very slowly about the line through two of its corners across the screen and spinning very slowly round its middle too, every next attack the other way round; it grows to a little wider than the playfield over eight beats and stays the whole attack. When the attack is over it comes apart into plain bullets half the size, flying out from its middle."),
            [BossMechanic.FallenAngel] = ("Every four beats two beams three circles wide come down from the top, one over where you are and one somewhere else: a faint see-through preview for four beats, then they hurt for four, coming down with Byakuren's beam sound.", "She stands in the middle; her big white wings come out of her, open and sway slowly, up a little and down as far as 45 degrees - their bones bending one after the other and every long feather trailing and fluttering on its own - and they hurt like a slider. Every bullet fired while her wings are out comes out of them instead, as a glowing feather, and flies away from a place below her (so also up over her)."),
            [BossMechanic.Jiangshi] = ("A fan of five knives with red handles at you every two beats.", "As Seiga: every fourth bullet that leaves the playfield turns back as a paper talisman twice as big and flies straight back the way it came at its own speed, for four beats, leaving copies of itself as big standing end to end behind it, each for eight beats."),
            [BossMechanic.Familiar] = ("A fan of twenty ellipses at you every two beats; every two neighbouring ellipses of a fan are joined by a beam over and over: see-through and harmless for a beat, hurting for two beats, gone for a beat.", "Socrates, her cat, twice as big as a bullet, comes out of her with a cry; every four beats it jumps onto a bullet within four circle radii of it - anyone's, the bosses' own too - and rides it - one whose leap goes over you if it can, else the one nearest you - and it jumps more often the further it is from you. Red arrows show where it will jump, a beat before. It hurts like a slider body, leaping too."),
            [BossMechanic.PipeFox] = ("A ring of six big balls, two circles across each, at you every four beats (her spinner too), each ring turned half a step from the last.", "Every fourth beam of her section bounces once off the edge of the screen. Every tenth bullet fired in her section comes out of her big balls instead, the six in turn, and flies on the way it was fired."),
            [BossMechanic.Haniwa] = ("A very dense square of plain bullets every four beats; in her spinner round bullets in squares.", "In her section the rings come half as often with twice as many bullets, and every ring is a square. Every fifth bullet that goes out of the screen comes back as two beams two beats long, 45 degrees to either side of the way it came (90 degrees apart), until they have crossed the screen. Every ring of the map is a square in her section, also those another boss changes."),
            [BossMechanic.Koto] = ("Beams eight times as thick as a normal one fall slowly from the top of the screen in 18 lanes, where an 18-key osu!mania convert of the map has its notes: an approach circle closes at the top of the lane first, then the note falls and reaches the bottom on its time: a tap is a round dot of beam, a held note a beam exactly as long as it is held.", "No pauses: the whole section is the convert, from her first beat to her last, over the map's own circles and sliders."),
            [BossMechanic.Strings] = ("Five parallel beams as thin as a slider's, wide apart, at you in her attacks, turning after you twice as fast as a spinner's beams as they fire, with Byakuren's beam sound every eight beats; in her spinner round bullets.", "Every slider's beam in her section has another one above it and below it, see-through and harmless for four beats. Every second bullet that crosses a beam becomes a note, white, with a soft glow: it flies at half its speed, swelling to twice its speed and back every two beats, and turns towards you once."),
            [BossMechanic.Snowflake] = ("One giant snowflake of beams after another, twice as big as the screen is wide and outlined in blue, standing still where she was (you are between two of its arms when it begins): six arms, eight times as thick as a slider's beam at the middle and narrowing evenly to half as thick at their tips; side branches, longest near the middle and shorter and fewer further out, with twigs and twigs of twigs, each four times as thick as a slider's where it starts and as thick at its end, all one seamless piece, every beam ending in a sharp tip; a see-through preview grows two beats ahead of it.", "No pauses. A snowflake grows from its middle out over eight beats, as Yuyuko's tree grows, then goes again from the middle out over the next eight, coming apart into plain bullets half the size that fly out from its middle; then the next one begins."),
            [BossMechanic.Galaxy] = ("Every quarter beat five endless straight beams round her, bent 20 degrees like the arms of a galaxy, their starts joined by beams into a five-pointed star, see-through and harmless for four beats, then solid for four, fading out over the last two; the sets go slowly through every colour of the rainbow; each set stays where she was when it came, and is turned five degrees from the last, the same way round for 32 beats and then the other way.", "No pauses. Every eight beats every second bullet on the screen turns into a star like Marisa's and ricochets once off the edge of the screen."),
            [BossMechanic.Metamorphosis] = ("Rings of sixteen blue butterflies every four beats, the first at you, in a spinner too: they flap their wings and drift out slowly, wandering from side to side as Wriggle's fireflies do.", "Every eight beats every tenth bullet on the screen (her butterflies too; sixty-four at most) turns aquamarine and flies at half its speed with a red ring round it, as Patchouli's fire, flashing faster and faster at the end. Four beats later it swells with Mokou's impact sound to a big round bullet two circle radii wide, glowing, at its own speed again, that hurts like a slider body; over the last beat of the next four it shrinks back. A butterfly stays a butterfly: it swells into a big butterfly."),
            [BossMechanic.Poltergeist] = ("A fan of three bullets twice as big as usual at you every eight beats.", "Every sixteen beats 64 bullets stop where they are; over four beats they grow to twice their size, turn white and glow, and a red arrow beside each shows the way it will go (blinking over the last beat). Eight beats after they stopped they fly off, each its own way, twice as fast, and ricochet off the edges of the screen three times."),
        };

        public const string PLACEHOLDER = "None yet: this boss is still a placeholder.";

        /// <summary>What the line of a boss's difficulty starts with: the number follows (<see cref="Mods.BossInfoPanel"/> shows it as stars).</summary>
        public const string DIFFICULTY = "Difficulty: ";

        /// <summary>A boss's difficulty and the two parts of her text, one line each.</summary>
        public static string Of(BossInfo boss)
        {
            var (basic, mechanics) = boss.IsModified && texts.TryGetValue(boss.Mechanic, out var text) ? text : (stars, PLACEHOLDER);
            return $"{DIFFICULTY}{BossDifficulty.Of(boss)}\nBasic Attack: {basic}\nMechanics: {mechanics}";
        }

        /// <summary>The things that mechanics change and that two mechanics can fight over: for each, what each mechanic does with it (the mechanics that are not in a list do nothing there).</summary>
        private static readonly (string Title, string Both, Dictionary<BossMechanic, string> Does)[] domains =
        {
            ("the edge of the screen", "Both change what happens to bullets at the edge of the screen", new Dictionary<BossMechanic, string>
            {
                [BossMechanic.FantasySeal] = "bullets stop there and pile up",
                [BossMechanic.Echo] = "glass walls bounce them",
                [BossMechanic.FreeFall] = "the top stops them and drops them",
                [BossMechanic.ButterflyFans] = "the top turns them into falling petals",
                [BossMechanic.Death] = "a ripple drops them",
                [BossMechanic.Return] = "they are shot again from her",
                [BossMechanic.Destruction] = "an explosion near you takes them and shoots them again",
                [BossMechanic.ScreenMirror] = "they bounce off it once",
                [BossMechanic.Shikigami] = "they bounce off it",
                [BossMechanic.ThreeWorlds] = "orbs ricochet off it",
                [BossMechanic.Necromancy] = "they come back at a quarter of the speed",
                [BossMechanic.Jiangshi] = "they come straight back with a trail of talismans",
                [BossMechanic.SevenElements] = "every tenth one grows a tree there in her wood phase",
                [BossMechanic.Spring] = "every one that leaves grows a flower on a branch there",
                [BossMechanic.Onbashira] = "what a boss shoots is red, and comes back the way it went, blue",
                [BossMechanic.Masks] = "in her aquamarine mood they ricochet off it three times",
                [BossMechanic.Patrol] = "the top and the bottom catch them into piles that crash in the middle",
                [BossMechanic.Myoga] = "the top sends them back down, the bottom leaves talismans aimed at you",
            }),
            ("time", "Both stop or freeze what is flying", new Dictionary<BossMechanic, string>
            {
                [BossMechanic.Freeze] = "everything freezes at the start of her attack",
                [BossMechanic.TimeStop] = "time stands still in her attacks",
                [BossMechanic.Lunatic] = "everything freezes in her attacks",
                [BossMechanic.Death] = "her ripple stops what it passes",
                [BossMechanic.Web] = "her web holds every second bullet that flies into it",
                [BossMechanic.Kasha] = "every bullet of her attacks stops and swells sixteen beats after it was fired",
                [BossMechanic.Komainu] = "every bullet stops and sets off at you over and over",
                [BossMechanic.Bamboo] = "every bullet moves and stands by turns, four beats each",
            }),
            ("what you can see", "Both take away your view", new Dictionary<BossMechanic, string>
            {
                [BossMechanic.Blindness] = "a flashlight is all you see",
                [BossMechanic.Smoke] = "smoke clouds make bullets see-through",
                [BossMechanic.Darkness] = "invisible circles hide the bullets in them",
                [BossMechanic.Unknown] = "shapes and colours hide until the bullets are close",
            }),
            ("the sliders", "Both rewrite every slider", new Dictionary<BossMechanic, string>
            {
                [BossMechanic.Purification] = "the lasers come from her",
                [BossMechanic.Frog] = "the lasers come from her, in a fan",
                [BossMechanic.Creation] = "the lasers come from her wings, straight",
                [BossMechanic.Winter] = "every slider shoots beams that dissipate into bullets",
                [BossMechanic.Vampire] = "every slider shoots a beam instead of bullets",
                [BossMechanic.Staff] = "the sliders' beams stand still, then fly off spinning",
                [BossMechanic.Curse] = "every slider throws a curse instead of its beam",
            }),
            ("the speed of the bullets", "Both change how fast the bullets fly", new Dictionary<BossMechanic, string>
            {
                [BossMechanic.Blindness] = "all bullets are half as fast in an attack",
                [BossMechanic.Volley] = "each bullet is shot three times in a row",
                [BossMechanic.HalfMoon] = "her moon bounces them off",
                [BossMechanic.Masks] = "her moods aim them at you, pull them at you, bounce them and drop them",
                [BossMechanic.Crescent] = "every bullet goes round her in her attacks",
                [BossMechanic.Statue] = "every bullet starts at a quarter speed until her wave doubles it",
                [BossMechanic.Gatekeeper] = "every bullet is twice as fast by her and a quarter as fast at the edge",
                [BossMechanic.Satellites] = "the bigger a bullet is, the slower it flies",
            }),
        };

        /// <summary>The text of a boss or of two bosses together: every boss with what he does, one after the other.</summary>
        public static string Combined(IReadOnlyList<BossInfo> bosses)
        {
            var parts = new List<string>();

            foreach (var boss in bosses)
                parts.Add($"{boss.Name}\n{Of(boss)}");

            return string.Join("\n\n", parts);
        }

        /// <summary>Where the mechanics of two bosses fight over the same thing, one sentence for each such thing; null if they do not (or there is only one boss).</summary>
        public static string? Clash(IReadOnlyList<BossInfo> bosses)
        {
            if (bosses.Count < 2)
                return null;

            var a = bosses[0];
            var b = bosses[1];
            var lines = new List<string>();

            foreach (var (_, both, does) in domains)
            {
                if (a.IsModified && b.IsModified && does.TryGetValue(a.Mechanic, out string? first) && does.TryGetValue(b.Mechanic, out string? second))
                    lines.Add($"{both}: {a.Name} - {first}; {b.Name} - {second}.");
            }

            if (a.IsModified && b.IsModified && a.Mechanic == b.Mechanic)
                lines.Add($"The same mechanic twice: {a.Name} and {b.Name} do the same thing at once.");

            return lines.Count == 0 ? null : string.Join("\n", lines);
        }
    }
}
